#nullable enable
namespace CardGame.Core.NativeOwners;
internal sealed class QuHuangNativeQueries(Func<RuntimeEntries.CoreActualTurnsEntries> getCoreActualTurnsRuntime, EngineStates.CoreMatchParticipantsState matchParticipantsState, Func<RuntimeEntries.CoreGameEngineProgramCardPoliciesEntries> getCoreGameEngineProgramCardPoliciesRuntime, Func<RuntimeEntries.CoreGameEngineCardUseModulesEntries> getCoreGameEngineCardUseModulesRuntime, Func<RuntimeEntries.CoreDirectedTurnCardPoliciesEntries> getCoreDirectedTurnCardPoliciesRuntime, Func<RuntimeEntries.CoreGameEngineHandComparisonEntries> getCoreGameEngineHandComparisonRuntime, Func<RuntimeEntries.CoreNativeDamagePoliciesEntries> getCoreNativeDamagePoliciesRuntime, Func<RuntimeEntries.CoreGameEngineDeckEquipmentProgramsEntries> getCoreGameEngineDeckEquipmentProgramsRuntime, Func<RuntimeEntries.CoreProgramParticipantPhaseOperationsEntries> getCoreProgramParticipantPhaseOperationsRuntime, Func<RuntimeEntries.CoreGameEngineCardUseLifecycleEntries> getCoreGameEngineCardUseLifecycleRuntime, Func<RuntimeEntries.CoreGameEngineShownEntityTurnPoliciesEntries> getCoreGameEngineShownEntityTurnPoliciesRuntime, Func<RuntimeEntries.CoreGameEngineCurrentUsePhysicalClaimsEntries> getCoreGameEngineCurrentUsePhysicalClaimsRuntime, Func<RuntimeEntries.CoreGameEngineAlternativeViewAsCostsEntries> getCoreGameEngineAlternativeViewAsCostsRuntime, Func<RuntimeEntries.CoreGameEngineRecoveryReplacementDamageRidesEntries> getCoreGameEngineRecoveryReplacementDamageRidesRuntime, Func<RuntimeEntries.CoreGameEngineObserverSubtreesEntries> getCoreGameEngineObserverSubtreesRuntime, Func<FrameStore> getFrameStore, Func<RuntimeEntries.DeferredRuntime<EngineOwners.CoreDyingCursorRuntimeRuntime>> getCoreDyingCursorRuntimeRuntime) : IQuHuangNativeQueries
{
    public bool HasJudgmentCard(int seat, CardKind kind) => getCoreActualTurnsRuntime().HasJudgmentEffectiveCard(matchParticipantsState.ReferenceToPlayers[seat], kind);
    public bool HasCardPolicy(int seat, SkillProgramCardPolicyKind policy) => getCoreGameEngineProgramCardPoliciesRuntime().HasCardPolicy(matchParticipantsState.ReferenceToPlayers[seat], policy);
