    public bool IsDirectedTargetProhibited(int actor, int target, CardKind kind) => getCoreDirectedTurnCardPoliciesRuntime().IsDirectedCardTargetProhibited(actor, target, kind);
    public bool IsSelfTargetForbidden(int seat, CardKind kind, IReadOnlyList<int> targets) => getCoreGameEngineHandComparisonRuntime().IsSelfTargetForbiddenAction(matchParticipantsState.ReferenceToPlayers[seat], kind, targets);
    public bool IsCardTargetProhibited(int seat, CardKind kind, Suit suit, bool? red) => getCoreNativeDamagePoliciesRuntime().IsCardTargetProhibited(matchParticipantsState.ReferenceToPlayers[seat], kind, suit, red);
    public bool HasBeneficiarySuitShield(int actor, int target, Suit suit) => getCoreGameEngineDeckEquipmentProgramsRuntime().HasBeneficiarySuitShield(actor, target, suit);
    public bool IsPhysicalUseForbidden(int actor, IReadOnlyList<int> cards) => getCoreProgramParticipantPhaseOperationsRuntime().IsTurnPhysicalUseForbidden(actor, cards);
    public bool IsSuitUseForbidden(int actor, Suit suit) => getCoreProgramParticipantPhaseOperationsRuntime().IsTurnSuitUseForbidden(actor, suit);
