    public bool UseActorMatches(CardUseFrame use, int actor, int provider) => getCoreGameEngineShownEntityTurnPoliciesRuntime().ShownEntityUseActorMatches(use, actor, provider);
    public int? NullificationTarget(NullificationWindowFrame window) => EngineOwners.CoreNativeNullificationFramesRuntime.GetNullificationTargetSeat(window);
