    public bool IsAlternativeCost(CardActionContext action, int card) => getCoreGameEngineAlternativeViewAsCostsRuntime().IsProgramAlternativeCost(action, card);
    public bool PaymentBatchMatchesReceipt(CardUseFrame use, CardMovementBatchContext batch) => EngineOwners.CoreGameEngineCardUsePaymentsRuntime.CardUsePaymentBatchMatchesReceipt(use, batch);
    public bool RecoveryRidesOn(ResolutionFrame child, ResolutionFrame parent) => getCoreGameEngineRecoveryReplacementDamageRidesRuntime().RecoveryReplacementFrameRidesOn(child, parent);
    public bool MovementReturnMatches(ProgramSkillFrame parent, CardsMovedTriggerWindowFrame child) => EngineOwners.CoreDamageObserverCursorQueriesRuntime.ProgramMovementReturnMatches(parent, child);
    public bool IsMovementObserverEdge(long childId) => getCoreGameEngineObserverSubtreesRuntime().IsMovementObserverEdge(getFrameStore().FindIndex(f => f.Id == childId));
    public bool IsSuspendedOrPaidRescueSuffix(long childId, DyingFrame dying) => getCoreGameEngineObserverSubtreesRuntime().IsSuspendedOrPaidRescueObserverSuffix(getFrameStore().FindIndex(f => f.Id == childId), dying);
    public DyingFrame? ActiveDying => getCoreDyingCursorRuntimeRuntime().Value.ActiveDying;
}
